    "cases.bill_the_month_with_a_payment_application.step.changes.out.net": "Nettó változás pótmunka-rendelésenként",
    "cases.bill_the_month_with_a_payment_application.step.certificate.in.lines": "Kitöltött folytatólap",
    "cases.bill_the_month_with_a_payment_application.step.certificate.in.previous": "Korábban igazolt összeg",
